package checkout

import (
 "encoding/base64"
 "encoding/json"
 "net/http"
 "strings"

 "github.com/jackc/pgx/v5"
 "github.com/masharzy/ekmivo/backend/internal/deviceevidence"
 "github.com/masharzy/ekmivo/backend/internal/merchantwebhook"
)

// Verified payer-group customers are generated by the read model; reveal the
// actual encrypted sender number only to owner/admin. Manually saved contacts
// retain their own name/phone and are never used to infer payment identity.
func (s *Service) supplementCustomerPayerNumbers(r *http.Request, ws, realm string, result any, role string) {
 if role!="owner" && role!="admin" {return}
 body,ok:=result.(map[string]any);if !ok{return}
 records,ok:=body["items"].([]any);if !ok||len(records)==0||len(records)>50{return}
 ids:=make([]string,0,len(records))
 byID:=make(map[string]map[string]any)
 for _,value:=range records {
  row,ok:=value.(map[string]any);if !ok{continue}
  content,ok:=row["body"].(map[string]any);if !ok||content["source"]!="checkout_payer"{continue}
  id,ok:=row["id"].(string);if !ok||!uuidPattern.MatchString(id){continue}
  ids=append(ids,id);byID[id]=content
 }
 if len(ids)==0{return}
 key,err:=json.Marshal(ids);if err!=nil{return}
 var raw []byte
 if err=s.pipelineScoped(r.Context(),ws,realm,func(tx pgx.Tx)error{
  return tx.QueryRow(r.Context(),"SELECT pg66_customer_payer_evidence($1::uuid,$2,$3::jsonb)",
   ws,realm,string(key)).Scan(&raw)
 });err!=nil{return} // Existing customer list remains available before migration.
 var encrypted []struct{
  ID string `json:"id"`
  Cipher string `json:"payer_cipher_b64"`
 }
 if json.Unmarshal(raw,&encrypted)!=nil{return}
 for _,record:=range encrypted {
  target:=byID[record.ID];if target==nil||record.Cipher==""{continue}
  cipher,err:=base64.StdEncoding.DecodeString(record.Cipher);if err!=nil{continue}
  plain,err:=merchantwebhook.Decrypt(s.Pipeline.Key,cipher,ws+"|"+realm+"|refund-customer");if err!=nil{continue}
  var contact struct{Phone string `json:"phone"`}
  if json.Unmarshal(plain,&contact)!=nil{continue}
  full,valid:=deviceevidence.NormalizeNumber(contact.Phone);if !valid{continue}
  target["phone"]=full
  if name,ok:=target["name"].(string);ok&&strings.HasPrefix(name,"Payer · "){
   target["name"]=full
  }
 }
}
